def pre_command(ctx):
    name = ctx['command']
    if name == 'touch':
        return {'kind': 'deny', 'reason': 'script says no'}
    if name == 'mkdir':
        return {'kind': 'ask', 'reason': 'mkdir needs a nod'}
    if name == 'rm' and ctx['env'].get('MODE') == 'safe':
        return {'kind': 'deny', 'reason': 'safe mode'}

def pre_vfs(ctx):
    if ctx['path'] == '/data/s':
        return {'kind': 'deny', 'reason': 'script guards s'}
    if ctx['path'] == '/data/held':
        return {'kind': 'ask', 'reason': 'held needs a nod'}

def pre_execute(ctx):
    names = [c['command'] for c in ctx['commands']]
    if 'false' in names and ctx['cwd'] == '/data':
        reason = 'no false in /data: ' + ' '.join(names)
        return {'kind': 'deny', 'reason': reason}

import os

def pre_command(ctx):
    if ctx['command'] == 'hostname':
        reason = 'cwd ' + os.getcwd() + ' team ' + str(ctx['env'].get('TEAM')) + ' env ' + ','.join(sorted(os.environ))
        return {'kind': 'deny', 'reason': reason}

def pre_command(ctx):
    if ctx['command'] in ('hostname', 'whoami'):
        return {'kind': 'ask', 'reason': ctx['command'] + ' needs a nod'}

def pre_vfs(ctx):
    if ctx['call']['name'] == 'read' and 'secret' in open(ctx['path']).read():
        return {'kind': 'deny', 'reason': 'secret text'}

def post_command(ctx):
    if ctx['command'] == 'echo':
        return {'kind': 'deny', 'reason': 'no echo after ' + str(ctx['exit_code'])}

import os

def pre_command(ctx):
    if ctx['command'] == 'rm':
        return {'kind': 'deny', 'reason': os.environ['WHY']}
    elif ctx['command'] == 'touch' and 'MODE' in os.environ:
        return {'kind': 'deny', 'reason': 'the session leaked in'}

def pre_command(ctx):
    if ctx['command'] in ('mv', 'rm'):
        return {'kind': 'deny', 'reason': 'subtree ' + str(ctx['subtree']) + ' into ' + str(ctx['move_target'])}
    if ctx['write']:
        return {'kind': 'deny', 'reason': 'writes'}

def pre_command(ctx):
    if ctx['command'] in ('cd', 'mkdir', 'echo', 'ln'):
        return None
    named = [w['text'] + ' ' + str(w['option']) + ' ' + w['path'] for w in ctx['words'] if w['path']]
    return {'kind': 'deny', 'reason': ', '.join(named) + ' | ' + ' '.join(ctx['paths'])}

def pre_command(ctx):
    if ctx['write']:
        return {'kind': 'deny', 'reason': 'read only'}
